  const shapes: PlanShape[] = [];
  const box = (
    x0: number,
    y0: number,
    z0: number,
    x1: number,
    y1: number,
    z1: number,
    id: number,
  ): void => {
    shapes.push({ kind: "box", min: [x0, y0, z0], max: [x1, y1, z1], id });
  };
